1. using System;
2. using System.Collections.Generic;
3. using System.Linq;
4. using LegacyTradeReconciliation.Domain;
5. 
6. namespace LegacyTradeReconciliation
7. {
8.     public sealed class MatchingEngine
9.     {
10.         public ReconciliationResult Reconcile(
11.             IReadOnlyCollection<TradeRecord> trades,
12.             IReadOnlyCollection<PositionRecord> positions,
13.             IReadOnlyCollection<SettlementRecord> settlements,
14.             IReadOnlyCollection<ManualOverrideRecord> overrides)
15.         {
16.             var matchedTrades = new List<MatchedTradeRecord>();
17.             var breakQueue = new List<BreakRecord>();
18.             var staleOverrides = new List<ManualOverrideRecord>();
19.             var overrideGroups = overrides.GroupBy(record => Normalize(record.TradeId), StringComparer.Ordinal).ToList();
20.             var overrideMap = overrideGroups.ToDictionary(group => group.Key, group => group.First(), StringComparer.Ordinal);
21.             staleOverrides.AddRange(overrideGroups.SelectMany(group => group.Skip(1)));
22. 
23.             var positionsByPair = positions
24.                 .GroupBy(position => BuildPairKey(position.Account, position.Instrument), StringComparer.Ordinal)
25.                 .ToDictionary(group => group.Key, group => group.OrderBy(position => position.PositionId, StringComparer.Ordinal).ToList(), StringComparer.Ordinal);
26. 
27.             var settlementsByPair = settlements
28.                 .GroupBy(settlement => BuildPairKey(settlement.Account, settlement.Instrument), StringComparer.Ordinal)
29.                 .ToDictionary(group => group.Key, group => group.OrderBy(settlement => settlement.SettlementId, StringComparer.Ordinal).ToList(), StringComparer.Ordinal);
30. 
31.             var usedPositions = new HashSet<string>(StringComparer.Ordinal);
32.             var usedSettlements = new HashSet<string>(StringComparer.Ordinal);
33.             var seenTradeIds = new HashSet<string>(StringComparer.Ordinal);
34.             int duplicateTradeCount = 0;
35. 
36.             foreach (var trade in trades)
37.             {
38.                 string normalizedTradeId = Normalize(trade.TradeId);
39.                 if (!seenTradeIds.Add(normalizedTradeId))
40.                 {
41.                     duplicateTradeCount++;
42.                     breakQueue.Add(CreateBreak(trade, "DuplicateTradeId", null, null, false));
43.                     continue;
44.                 }
45. 
46.                 if (trade.Quantity <= 0m || trade.NetAmount <= 0m)
47.                 {
48.                     breakQueue.Add(CreateBreak(trade, "TradeValueOutOfBounds", null, null, false));
49.                     continue;
50.                 }
51. 
52.                 string pairKey = BuildPairKey(trade.Account, trade.Instrument);
53.                 PositionRecord position = null;
54.                 SettlementRecord settlement = null;
55.                 var reasons = new List<string>();
56. 
57.                 List<PositionRecord> positionCandidates;
58.                 if (!positionsByPair.TryGetValue(pairKey, out positionCandidates))
59.                 {
60.                     reasons.Add("MissingPosition");
61.                 }
62.                 else
63.                 {
64.                     position = FindPosition(trade, positionCandidates, usedPositions, reasons);
65.                 }
66. 
67.                 List<SettlementRecord> settlementCandidates;
68.                 if (!settlementsByPair.TryGetValue(pairKey, out settlementCandidates))
69.                 {
70.                     reasons.Add("MissingSettlement");
71.                 }
72.                 else
73.                 {
74.                     settlement = FindSettlement(trade, settlementCandidates, usedSettlements, reasons);
75.                 }
76. 
77.                 if (reasons.Count == 0 && position != null && settlement != null)
78.                 {
79.                     usedPositions.Add(position.PositionId);
80.                     usedSettlements.Add(settlement.SettlementId);
81.                     matchedTrades.Add(CreateMatchedTrade(trade, "Matched", position.PositionId, settlement.SettlementId, null));
82.                     continue;
83.                 }
84. 
85.                 breakQueue.Add(CreateBreak(
86.                     trade,
87.                     string.Join("|", reasons.Distinct(StringComparer.Ordinal).OrderBy(reason => reason, StringComparer.Ordinal)),
88.                     position != null ? position.PositionId : GetNearestPositionId(trade, positionCandidates),
89.                     settlement != null ? settlement.SettlementId : GetNearestSettlementId(trade, settlementCandidates),
90.                     positionCandidates != null && settlementCandidates != null && reasons.All(reason => reason != "MissingPosition" && reason != "MissingSettlement" && reason != "DuplicateTradeId" && reason != "TradeValueOutOfBounds")));
91.             }
92. 
93.             var resolvedTrades = new HashSet<string>(StringComparer.Ordinal);
94.             foreach (var breakRecord in breakQueue.ToList())
95.             {
96.                 ManualOverrideRecord manualOverride;
97.                 if (!overrideMap.TryGetValue(Normalize(breakRecord.TradeId), out manualOverride))
98.                 {
99.                     continue;
100.                 }
101. 
102.                 resolvedTrades.Add(Normalize(breakRecord.TradeId));
103.                 if (!breakRecord.CanManualOverride || string.IsNullOrWhiteSpace(manualOverride.Note) || string.IsNullOrWhiteSpace(manualOverride.ApprovedBy))
104.                 {
105.                     staleOverrides.Add(manualOverride);
106.                     continue;
107.                 }
108. 
109.                 string action = Normalize(manualOverride.Action);
110.                 if (action == "FORCEMATCH")
111.                 {
112.                     matchedTrades.Add(CreateMatchedTrade(
113.                         new TradeRecord
114.                         {
115.                             TradeId = breakRecord.TradeId,
116.                             Account = breakRecord.Account,
117.                             Instrument = breakRecord.Instrument,
118.                             Quantity = breakRecord.Quantity,
119.                             SettlementDate = breakRecord.SettlementDate,
120.                             Currency = breakRecord.Currency
121.                         },
122.                         "ManualOverrideMatched",
123.                         breakRecord.PositionId,
124.                         breakRecord.SettlementId,
125.                         manualOverride.Note));
126.                     breakQueue.Remove(breakRecord);
127.                 }
128.                 else if (action == "SUPPRESSBREAK")
129.                 {
130.                     matchedTrades.Add(CreateMatchedTrade(
131.                         new TradeRecord
132.                         {
133.                             TradeId = breakRecord.TradeId,
134.                             Account = breakRecord.Account,
135.                             Instrument = breakRecord.Instrument,
136.                             Quantity = breakRecord.Quantity,
137.                             SettlementDate = breakRecord.SettlementDate,
138.                             Currency = breakRecord.Currency
139.                         },
140.                         "ManualOverrideSuppressed",
141.                         breakRecord.PositionId,
142.                         breakRecord.SettlementId,
143.                         manualOverride.Note));
144.                     breakQueue.Remove(breakRecord);
145.                 }
146.                 else
147.                 {
148.                     staleOverrides.Add(manualOverride);
149.                 }
150.             }
151. 
152.             staleOverrides.AddRange(overrides.Where(record => !resolvedTrades.Contains(Normalize(record.TradeId)) && !staleOverrides.Contains(record)));
153. 
154.             return new ReconciliationResult
155.             {
156.                 MatchedTrades = matchedTrades.OrderBy(record => record.TradeId, StringComparer.Ordinal).ToList(),
157.                 OpenBreaks = breakQueue.OrderBy(record => record.TradeId, StringComparer.Ordinal).ToList(),
158.                 StaleOverrides = staleOverrides.OrderBy(record => record.TradeId, StringComparer.Ordinal).ToList(),
159.                 TotalTradesRead = trades.Count,
160.                 CanonicalTradeCount = seenTradeIds.Count,
161.                 DuplicateTradeCount = duplicateTradeCount,
162.                 MatchedCount = matchedTrades.Count(record => record.Status == "Matched"),
163.                 ManualOverrideMatchedCount = matchedTrades.Count(record => record.Status == "ManualOverrideMatched"),
164.                 ManualOverrideSuppressedCount = matchedTrades.Count(record => record.Status == "ManualOverrideSuppressed")
165.             };
166.         }
167. 
168.         private static PositionRecord FindPosition(TradeRecord trade, IEnumerable<PositionRecord> candidates, ISet<string> usedPositions, ICollection<string> reasons)
169.         {
170.             var available = candidates.Where(candidate => !usedPositions.Contains(candidate.PositionId)).ToList();
171.             if (!available.Any())
172.             {
173.                 reasons.Add("MissingPosition");
174.                 return null;
175.             }
176. 
177.             var sameDate = available.Where(candidate => candidate.SettlementDate == trade.SettlementDate).ToList();
178.             if (!sameDate.Any())
179.             {
180.                 reasons.Add("PositionSettlementDateMismatch");
181.                 return null;
182.             }
183. 
184.             var sameCurrency = sameDate.Where(candidate => Normalize(candidate.Currency) == Normalize(trade.Currency)).ToList();
185.             if (!sameCurrency.Any())
186.             {
187.                 reasons.Add("PositionCurrencyMismatch");
188.                 return null;
189.             }
190. 
191.             var candidatePosition = sameCurrency
192.                 .OrderBy(candidate => Math.Abs(candidate.Quantity - trade.Quantity))
193.                 .ThenBy(candidate => candidate.PositionId, StringComparer.Ordinal)
194.                 .First();
195. 
196.             if (Math.Sign((double)candidatePosition.Quantity) != Math.Sign((double)trade.Quantity))
197.             {
198.                 reasons.Add("PositionQuantitySignMismatch");
199.                 return null;
200.             }
201. 
202.             if (Math.Abs(candidatePosition.Quantity - trade.Quantity) > BatchConfiguration.PositionQuantityTolerance)
203.             {
204.                 reasons.Add("PositionQuantityOutOfTolerance");
205.                 return null;
206.             }
207. 
208.             return candidatePosition;
209.         }
210. 
211.         private static SettlementRecord FindSettlement(TradeRecord trade, IEnumerable<SettlementRecord> candidates, ISet<string> usedSettlements, ICollection<string> reasons)
212.         {
213.             var available = candidates.Where(candidate => !usedSettlements.Contains(candidate.SettlementId)).ToList();
214.             if (!available.Any())
215.             {
216.                 reasons.Add("MissingSettlement");
217.                 return null;
