private static void ExecuteBatch(string fixtureRoot, string outputDirectory)
{
    string workspaceRoot = FindWorkspaceRoot();
    string appProjectPath = Path.Combine(workspaceRoot, "LegacyTradeReconciliation", "LegacyTradeReconciliation.csproj");
    string inputDirectory = Path.Combine(fixtureRoot, "input");

    var startInfo = new ProcessStartInfo
    {
        FileName = "dotnet",
        Arguments = string.Format(
            "run --project \"{0}\" --configuration Release -- \"2025-03-17\" \"{1}\" \"{2}\"",
            appProjectPath,
            inputDirectory,
            outputDirectory),
        WorkingDirectory = workspaceRoot,
        RedirectStandardOutput = true,
        RedirectStandardError = true,
        UseShellExecute = false
    };

    using (var process = Process.Start(startInfo))
    {
        string stdout = process.StandardOutput.ReadToEnd();
        string stderr = process.StandardError.ReadToEnd();
        process.WaitForExit();

        if (process.ExitCode != 0)
        {
            throw new InvalidOperationException(
                "Batch exited with code " + process.ExitCode + "." + Environment.NewLine +
                stdout + Environment.NewLine + stderr);
        }
    }
}

private static string FindWorkspaceRoot()
{
    DirectoryInfo directory = new DirectoryInfo(AppDomain.CurrentDomain.BaseDirectory);
    while (directory != null)
    {
        if (Directory.Exists(Path.Combine(directory.FullName, "LegacyTradeReconciliation")) &&
            File.Exists(Path.Combine(directory.FullName, "LegacyTradeReconciliation.sln")))
        {
            return directory.FullName;
        }

        directory = directory.Parent;
    }

    throw new DirectoryNotFoundException("Unable to locate the workspace root.");
}

